Route::view('/login', 'workspace')->name('login');
Route::view('/register', 'workspace');
Route::view('/join/{inviteToken}', 'workspace')->where('inviteToken', '[a-f0-9]{64}');
Route::middleware('auth')->group(function () {
    Route::view('/', 'workspace');
    Route::get('/control/{section?}/{characterId?}', [WorkspaceController::class, 'library'])->where('section', 'characters|items|spells|npcs|assets')->where('characterId', 'new|[0-9]+');
    Route::get('/campaigns/{campaign}', [WorkspaceController::class, 'campaign']);
    Route::get('/campaigns/{campaign}/control/{section?}/{characterId?}', [WorkspaceController::class, 'control'])->where('section', 'characters')->where('characterId', 'new|[0-9]+');
    Route::get('/campaigns/{campaign}/play', [WorkspaceController::class, 'play']);
    Route::get('/campaigns/{campaign}/scenes', [WorkspaceController::class, 'campaign']);
    Route::get('/campaigns/{campaign}/scenes/{scene}', [WorkspaceController::class, 'scene']);
});

